"use client";

import { useState } from "react";
import Image from "next/image";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Carousel,
  CarouselContent,
  CarouselItem,
  CarouselNext,
  CarouselPrevious,
} from "@/components/ui/carousel";

const kegiatanList = [
  {
    src: "/kegiatan1.jpg",
    title: "Pramuka",
    desc: "Melatih kedisiplinan, kepemimpinan, dan kerjasama tim melalui kegiatan kepramukaan rutin.",
    gallery: ["/kegiatan1.jpg", "/pramuka2.jpg", "/pramuka3.jpg"],
  },
  {
    src: "/kegiatan2.jpg",
    title: "Upacara Bendera",
    desc: "Menanamkan rasa cinta tanah air dan kedisiplinan.",
    gallery: ["/kegiatan2.jpg", "/upacara2.jpg", "/upacara3.jpg"],
  },
  {
    src: "/kegiatan3.jpg",
    title: "Lomba 17 Agustus",
    desc: "Meningkatkan kreativitas dan semangat kebersamaan antar siswa.",
    gallery: ["/kegiatan3.jpg", "/lomba2.jpg", "/lomba3.jpg"],
  },
];

export default function KegiatanSection() {
  const [open, setOpen] = useState(false);
  const [selected, setSelected] = useState<typeof kegiatanList[0] | null>(null);

  const handleOpen = (item: typeof kegiatanList[0]) => {
    setSelected(item);
    setOpen(true);
  };

  return (
    <>
      <section className="max-w-screen-xl mx-auto px-4 py-12">
        <h2 className="text-3xl font-bold text-center mb-12">Kegiatan Siswa</h2>

        <div className="grid gap-8 sm:grid-cols-2 lg:grid-cols-3">
          {kegiatanList.map((item, index) => (
            <div
              key={index}
              onClick={() => handleOpen(item)}
              className="group rounded-xl overflow-hidden shadow-lg transition-transform transform hover:scale-[1.02] hover:shadow-xl bg-white cursor-pointer"
            >
              <div className="relative w-full">
                <Image
                  src={item.src}
                  alt={item.title}
                  width={800}
                  height={450}
                  layout="responsive"
                  className="rounded-t-xl object-cover transition duration-300 group-hover:scale-105"
                  loading="lazy"
                />
              </div>
              <div className="p-4">
                <h3 className="text-xl font-semibold mb-1">{item.title}</h3>
                <p className="text-sm text-gray-600">{item.desc}</p>
              </div>
            </div>
          ))}
        </div>
      </section>

      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent className="max-w-5xl p-6">
          {selected && (
            <>
              <DialogHeader>
                <DialogTitle>{selected.title}</DialogTitle>
              </DialogHeader>

              <p className="text-sm text-gray-600 mb-4">{selected.desc}</p>

              <Carousel className="w-full">
                <CarouselContent>
                  {selected.gallery.map((img, i) => (
                    <CarouselItem key={i} className="w-full">
                      <Image
                        src={img}
                        alt={`${selected.title} ${i + 1}`}
                        width={1280}
                        height={720}
                        layout="responsive"
                        className="rounded-xl object-cover"
                        loading="lazy"
                      />
                    </CarouselItem>
                  ))}
                </CarouselContent>
                <CarouselPrevious />
                <CarouselNext />
              </Carousel>
            </>
          )}
        </DialogContent>
      </Dialog>
    </>
  );
}
